import{_,o as a,c as e,a3 as t}from"./chunks/framework.DdpBa4_E.js";const s="/ReadBooks/assets/image-055.DvQHFPz_.jpg",h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/xialiu-shehui/16-针对上流阶层的销售需运用“上流化”的策略.md","filePath":"books/xialiu-shehui/16-针对上流阶层的销售需运用“上流化”的策略.md","lastUpdated":1794732511000}'),o={name:"books/xialiu-shehui/16-针对上流阶层的销售需运用“上流化”的策略.md"};function i(r,p,l,n,d,c){return a(),e("div",null,[...p[0]||(p[0]=[t('<h2 id="针对上流阶层的销售需运用-上流化-的策略" tabindex="-1">针对上流阶层的销售需运用“上流化”的策略 <a class="header-anchor" href="#针对上流阶层的销售需运用-上流化-的策略" aria-label="Permalink to &quot;针对上流阶层的销售需运用“上流化”的策略&quot;">​</a></h2><p>但是，今后中流阶层的人数势将越来越少，倘使其中一部分人群进入上层的话，那么，专门针对上流阶层生产制造商品和销售商品的策略将尤显必要。</p><p>如前所述，1996年以后中流阶层的人数减少，下流阶层的人数增加，而上流阶层的人数基本保持不变或略有增加。我们假定到201×年，上流阶层的人数增加至15%，中流阶层的人数减少至45%，下流阶层的人数增加至40%（见图1-4），又会出现怎样的情形呢？</p><p>10万日元×15万人＝150亿日元</p><p>7万日元×45万人＝315亿日元</p><p>3万日元×40万人＝120亿日元</p><p>总销售额为585亿日元，较1973年时的中流化模式呈现减少的结果。不言而喻，这是因为中流阶层中人数有所减少而造成的，“中流”的销售额总共减少了133亿日元，而“下流”的销售额仅增加33亿日元。不过，“上流”的销售额却增加了70亿日元，几乎增加了近一倍。</p><p><img src="'+s+'" alt="" loading="lazy"></p><p>图1-4　中流意识的变化之二（1973—201×年）</p><p>资料出处：数据源自内阁府进行的“国民生活意识调查”，由三浦展绘制，其中201×年部分由Culture Studies研究所绘制然而，看看百货商店的实际销售数字可以发现，自“泡沫经济”崩溃以来，几乎每年都比前一年有大幅的减少，其幅度远远不止是从615亿减少至585亿。这可能是由于通货紧缩造成的，原本能够购买7万日元商品的“中流”渐渐向“下流”靠拢，只能购买5万日元的商品了，这也就是一般所称的“优衣库现象”。</p><p>这样的话，实际销售额则为：</p><p>10万日元×15万人＝150亿日元</p><p>5万日元×45万人＝225亿日元</p><p>3万日元×40万人＝120亿日元</p><p>合计销售额为495亿日元，仅为1973年模式的80%。考虑到百货商店业的销售业绩比“泡沫经济”时代还要减少3至4成，因此基本上就是属于这一模式。这其实是因为市场已经从“中流社会”向“等级化社会”或“下流社会”转变了，而生产者的生产制造模式以及商业经营者的销售模式却仍然停留在中流社会的模式上，以这种不变的模式来应对业已变化了的市场，销售额减少也是理所当然的了。简单来说，就是百货商店销售额的逐年减少，其实是从1973年模式向201×年模式转变失败的结果。</p><p>如果想使销售额回升，百货商店又该如何做呢？</p><p>倘若“中流”和“下流”都能恢复至购买得起原来价格水平的商品的话自然是再好不过了，但即使是这样，总的销售额仍然是减少的，因为“中流”的人数减少了。如果将“中流”的商品价格由7万日元提高至8万日元，将“下流”的商品价格由3万日元提高至4万日元，结果会如何？消费者会购买吗？显然是很困难的，且不说“下流”的人群很难接受，就是“中流”的人群其意识也已经下流化了，他们变得只愿意选购便宜的商品。</p><p>究竟应该怎样才能提升销售额？还不如提升“上流”的商品价格。假设将商品价格由10万日元提升为15万日元，则15万日元×15万人＝225亿日元5万日元×45万人＝225亿日元3万日元×40万人＝120亿日元总销售额为570亿日元，仍然未及1973年模式的销售额。如果想要超过1973年模式的销售额，必须设法使上流阶层的消费者能够购买20万日元的西服（或者购买2件价格10万日元的西服）。</p><p>20万日元×15万人＝300亿日元</p><p>5万日元×45万人＝225亿日元</p><p>3万日元×40万人＝120亿日元</p><p>合计销售额为645亿日元，如此方才能够超过1973年模式的销售额。可见，要将中流阶层人数减少所造成的销售额减少部分弥补回来有多么困难。</p>',22)])])}const m=_(o,[["render",i]]);export{h as __pageData,m as default};
